-- SEC-5 phase-2 compatibility matrix. Every query shape the OLD client (staging/priv-rehearsal-r4) and the NEW client (this branch) send
-- to hosted_games / join_requests / game_payment_settings / game_position_waitlist / user_reports and the SEC-5 views (inventory:
-- docs/privacy/sec5-client-query-inventory.json, generated by scripts/sec5-client-query-inventory.mjs), plus the hand-written direct API
-- calls an attacker can make, run as the API role that sends them, written as the SQL PostgREST generates for them:
--   select=*                      -> SELECT "t".* ...                    (any ungranted column: "permission denied for table")
--   HEAD + count=exact            -> WITH pgrst_source AS (SELECT "t".* ...) SELECT (SELECT count(*) FROM (SELECT 1 ...)), count(_t) ...
--   return=minimal / representation -> INSERT ... RETURNING 1 / RETURNING "t".*
--   upsert (on_conflict=a,b)      -> INSERT ... ON CONFLICT (a,b) DO UPDATE SET c = EXCLUDED.c for every payload column
--   host_id=eq.X / order=host_id  -> WHERE "t"."host_id" = X / ORDER BY "t"."host_id"
-- Each probe runs in its own savepoint and is rolled back, so probes are independent and leave nothing behind.
--
-- States (plus r: phase 2 then supabase/phase2/sec5_phase2_rollback.sql, which must answer exactly like b): (a) pre-release schema (r4 without SEC-5): this file detects it (no hosted_games_public) and runs only the a-column; run it by
-- hand against an r4 replay (docs/privacy/sec5-public-organizer-ref.md, "Phase 2 compatibility results"). (b) SEC-5 phase 1 (this
-- branch's migrations). (c) phase 1 + phase 2 (supabase/phase2/sec5_phase2_close_host_id_columns.sql applied inside this transaction).
--
-- Result classes: ok (rows came back / rows changed), none (0 rows), leak (the minor host's account id, or their legacy username, is in
-- what came back, or an oracle filter on it matched), denied (42501: column/table privilege or row security WITH CHECK), missing (the
-- relation or column does not exist in that schema), error:<sqlstate> (anything else). A line "matrix|..." is printed per probe.
BEGIN;
GRANT SELECT, INSERT, UPDATE, DELETE ON storage.objects TO authenticated, anon, service_role;

SELECT to_regclass('public.hosted_games_public') IS NOT NULL AS sec5 \gset
\if :sec5
  \set state b
\else
  \set state a
\endif

SELECT t.person('teen', 17), t.person('mom', 45), t.person('grown', 35), t.person('stranger', 33), t.person('asker', 28),
       t.person('appr', 29), t.person('pal', 30), t.person('wl', 26), t.person('joiner', 27), t.person('payer', 31);
SELECT t.guardian('mom', 'teen');
