-- One probe: run _sql as _actor in a savepoint that is always rolled back, and classify the outcome.
CREATE FUNCTION t.probe511(_actor text, _kind text, _sql text, _needle text, _oracle boolean) RETURNS text[] LANGUAGE plpgsql AS $$
DECLARE _n bigint := 0; _hit boolean := false; _cls text; _detail text; _q text;
BEGIN
  -- {handle} -> that person's (or fixture's) id
  IF _needle ~ '^\{[a-z_0-9]+\}$' THEN _needle := t.id(substring(_needle FROM '^\{([a-z_0-9]+)\}$'))::text; END IF;
  _q := _sql;
  WHILE _q ~ '\{[a-z_0-9]+\}' LOOP
    _q := regexp_replace(_q, '\{([a-z_0-9]+)\}', t.id(substring(_q FROM '\{([a-z_0-9]+)\}'))::text);
  END LOOP;
  BEGIN
    IF _actor = 'anon' THEN PERFORM t.as_anon(); ELSE PERFORM t.as_user(t.id(_actor)); END IF;
    IF _kind = 'dml' THEN
      EXECUTE _q;
      GET DIAGNOSTICS _n = ROW_COUNT;
    ELSIF _kind = 'dml_ret' THEN
      EXECUTE format('WITH _p AS (%s) SELECT count(*), coalesce(bool_or(to_jsonb(_p)::text LIKE %L), false) FROM _p', _q, '%' || _needle || '%') INTO _n, _hit;
    ELSE
      EXECUTE format('SELECT count(*), coalesce(bool_or(to_jsonb(_p)::text LIKE %L), false) FROM (%s) _p', '%' || _needle || '%', _q) INTO _n, _hit;
    END IF;
    _cls := CASE WHEN _hit OR (_oracle AND _n > 0) THEN 'leak' WHEN _n = 0 THEN 'none' ELSE 'ok' END;
    _detail := _n || ' row(s)';
    RAISE EXCEPTION USING ERRCODE = 'P0511';
  EXCEPTION
    WHEN SQLSTATE 'P0511' THEN NULL;
    WHEN insufficient_privilege THEN _cls := 'denied'; _detail := SQLERRM;
    WHEN undefined_table OR undefined_column OR undefined_function THEN _cls := 'missing'; _detail := SQLERRM;
    WHEN OTHERS THEN _cls := 'error:' || SQLSTATE; _detail := SQLERRM;
  END;
  RETURN ARRAY[_cls, replace(_detail, E'\n', ' ')];
END $$;

