-- Run every probe in this state, then (in b) apply phase 2 and run them again as c.
CREATE TEMP TABLE results511 (state text, id text, cls text, detail text, PRIMARY KEY (state, id)) ON COMMIT DROP;
INSERT INTO results511 SELECT :'state', s.id, r[1], r[2] FROM shapes511 s CROSS JOIN LATERAL t.probe511(s.actor, s.kind, s.sql, s.needle, s.oracle) r;

\if :sec5
\ir ../phase2/sec5_phase2_close_host_id_columns.sql
INSERT INTO results511 SELECT 'c', s.id, r[1], r[2] FROM shapes511 s CROSS JOIN LATERAL t.probe511(s.actor, s.kind, s.sql, s.needle, s.oracle) r;
-- (r) the prepared rollback, applied on top of phase 2 in the same transaction: every probe must answer exactly as in phase 1
SAVEPOINT before_rollback511;
\ir ../phase2/sec5_phase2_rollback.sql
INSERT INTO results511 SELECT 'r', s.id, r[1], r[2] FROM shapes511 s CROSS JOIN LATERAL t.probe511(s.actor, s.kind, s.sql, s.needle, s.oracle) r;
SELECT t.eq((SELECT array_agg(r.id ORDER BY r.id) FROM results511 r JOIN results511 b ON b.id = r.id AND b.state = 'b' WHERE r.state = 'r' AND r.cls IS DISTINCT FROM b.cls),
            NULL::text[], 'ROLLBACK: after phase 2 and the rollback script, every probe answers as in phase 1 (old clients work again)');
SELECT t.ok(NOT has_column_privilege('authenticated', 'public.user_reports', 'reported_id', 'SELECT')
            AND NOT has_column_privilege('authenticated', 'public.game_position_waitlist', 'reviewed_by', 'SELECT'),
  'ROLLBACK: the phase-1 closures (reported_id, reviewed_by) stay closed');
ROLLBACK TO SAVEPOINT before_rollback511;
\endif

-- The matrix, one line per shape (not an assertion: the runner only counts "ok - " / "not ok - " lines).
DO $print$
DECLARE r record;
BEGIN
  FOR r IN SELECT s.id, s.client, s.label, a.cls AS a, b.cls AS b, c.cls AS c, coalesce(c.detail, b.detail, a.detail) AS detail
             FROM shapes511 s LEFT JOIN results511 a ON a.id = s.id AND a.state = 'a' LEFT JOIN results511 b ON b.id = s.id AND b.state = 'b'
             LEFT JOIN results511 c ON c.id = s.id AND c.state = 'c' ORDER BY s.id LOOP
    RAISE NOTICE 'matrix|%|%|%|%|%|%|%', r.id, r.client, r.label, coalesce(r.a, '-'), coalesce(r.b, '-'), coalesce(r.c, '-'), left(r.detail, 120);
  END LOOP;
END $print$;

-- One assertion per shape and state.
SELECT t.eq(r.cls, CASE r.state WHEN 'a' THEN s.exp_a WHEN 'b' THEN s.exp_b ELSE s.exp_c END,
            format('%s (%s) state %s: %s', s.id, s.client, r.state, s.label))
  FROM results511 r JOIN shapes511 s USING (id) WHERE r.state <> 'r' ORDER BY s.id, r.state;

-- The minimum-client-generation flag (src/lib/client-generation.ts) is a public app_settings row every build can read, signed in or not.
INSERT INTO public.app_settings (key, value, description, is_public) VALUES ('client_min_generation', '{"min": 5}', 'Oldest client generation the database still serves', true)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, is_public = true;
SELECT t.as_anon();
SELECT t.eq((SELECT (value ->> 'min')::int FROM public.app_settings WHERE key = 'client_min_generation'), 5, 'an anonymous visitor reads the minimum client generation');
SELECT t.reset();
SELECT t.as_user(t.id('stranger'));
SELECT t.eq((SELECT (value ->> 'min')::int FROM public.app_settings WHERE key = 'client_min_generation'), 5, 'so does a signed-in account');
SELECT t.reset();

-- The release blocker, stated as sets.
\if :sec5
SELECT t.eq((SELECT array_agg(id ORDER BY id) FROM results511 r JOIN shapes511 s USING (id) WHERE s.client = 'old' AND r.state = 'c' AND r.cls IN ('denied', 'missing')),
            ARRAY['O01','O02','O03','O04','O05','O06','O07','O08','O09','O10','O11','O12','O14','O15','O16'],
  'BLOCKER: these old-client calls fail after phase 2 (old bundles must be gone first)');
SELECT t.eq((SELECT array_agg(id ORDER BY id) FROM results511 r JOIN shapes511 s USING (id) WHERE s.client IN ('old', 'direct') AND r.state = 'b' AND r.cls = 'leak'),
            ARRAY['D01','D02','D03','D04','D06','D07','D11','O01','O02','O06','O08','O09','O10','O14'],
  'BLOCKER: with phase 1 only, these direct-API reads (and the old client''s own) still hand a stranger/requester the minor host''s id');
SELECT t.eq((SELECT count(*)::int FROM results511 r JOIN shapes511 s USING (id) WHERE s.client IN ('new', 'both') AND r.state IN ('b', 'c') AND (r.cls IN ('denied', 'missing', 'leak') OR r.cls LIKE 'error:%')
               AND s.area <> 'ownership'), 0,
  'no new-client (or shared) call fails or leaks in phase 1 or after phase 2');
SELECT t.eq((SELECT count(*)::int FROM results511 WHERE state = 'c' AND cls = 'leak'), 0, 'after phase 2 no probe, in any client or by hand, returns the minor host''s id');
\endif
ROLLBACK;
